function copy(o){var r={},k;for(k in o)if(Object.prototype.hasOwnProperty.call(o,k))r[k]=o[k];return r}
function apply(f,e){var r=copy(f),i,k,z=e.remove||[];for(i=0;i<z.length;i++)delete r[z[i]];z=e.set||{};for(k in z)if(Object.prototype.hasOwnProperty.call(z,k))r[k]=z[k];return r}
function solve(q){var s=q.state,e=q.event,id,x,a,o;if(s===null)s={f:copy(q.config.fields),r:0,st:'idle',owner:null,p:{},seen:{}};if(e.type==='edit'){s.f=apply(s.f,e);s.r++;s.st='idle'}else if(e.type==='submit'){id=e.id;if(!Object.prototype.hasOwnProperty.call(s.seen,id)){s.seen[id]=1;s.p[id]={pre:copy(s.f),rev:s.r+1};s.f=apply(s.f,e);s.r++;s.owner=id;s.st='saving'}}else if(e.type==='success'||e.type==='failure'){id=e.id;if(Object.prototype.hasOwnProperty.call(s.p,id)){x=s.p[id];delete s.p[id];if(s.owner===id&&x.rev===s.r){if(e.type==='success'){s.f=copy(e.fields);s.r++;s.st='saved'}else{s.f=copy(x.pre);s.r++;s.st='error'}s.owner=null}}}a=Object.keys(s.p).sort();o={fields:copy(s.f),revision:s.r,status:s.st,pending:a};return{state:s,output:o}}
